/* ============================== 스토리지 ============================== */
async function loadData(){ try{ return await getData(STORAGE_KEY); }catch{ return null; } }
async function persist(d){ try{ return await setData(STORAGE_KEY, d); }catch(e){ console.error(e); return false; } }

/* ============================== 스타일 ============================== */
const STYLES = `
@import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable.css');
@import url('https://fonts.googleapis.com/css2?family=Anton&family=Cormorant+Garamond:wght@500;600;700&display=swap');
.ypl{
  --bg:#F6FAFE;--bg2:#ECF3FB;--card:#FFFFFF;
  --line:rgba(20,40,68,.10);--line2:rgba(20,40,68,.20);
  --navy:#15273F;--navy2:#1E3A5F;--ink:#0D1B2E;
  --cyan:#1E84C6;--cyan-d:#13639B;--cyan-l:#2E9BDC;
  --gold:#B8861E;--gold-l:#D6A63A;--mint:#1AA386;
  --text:#162A45;--muted:#5C6E89;--muted2:#8696AE;--win:#0E9D6A;--loss:#D6455C;
  font-family:'Pretendard Variable',Pretendard,-apple-system,system-ui,sans-serif;
  color:var(--text);background:var(--bg);min-height:100vh;position:relative;overflow-x:hidden;
  -webkit-font-smoothing:antialiased;letter-spacing:-.01em;scroll-behavior:smooth;
}
.ypl *{box-sizing:border-box;}
html{overflow-y:scroll;scrollbar-gutter:stable;}
.ypl ::selection{background:rgba(30,132,198,.22);}
.disp{font-family:'Anton',sans-serif;font-weight:400;letter-spacing:.02em;}
.tnum{font-variant-numeric:tabular-nums;}
/* light aurora: 옅은 시안/민트 + 짙은 남색 그라데이션 포인트 */
.aurora{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden;}
.aurora i{position:absolute;border-radius:50%;filter:blur(90px);}
.aurora .a1{width:680px;height:680px;top:-260px;right:-140px;background:radial-gradient(circle,rgba(30,132,198,.26),transparent 68%);animation:drift 20s ease-in-out infinite;}
.aurora .a2{width:560px;height:560px;top:240px;left:-200px;background:radial-gradient(circle,rgba(26,163,134,.16),transparent 70%);animation:drift 25s ease-in-out infinite reverse;}
.aurora .a3{width:620px;height:620px;bottom:-280px;right:8%;background:radial-gradient(circle,rgba(21,39,63,.14),transparent 68%);animation:drift 30s ease-in-out infinite;}
.aurora .grid{position:absolute;inset:0;background:linear-gradient(rgba(21,39,63,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(21,39,63,.04) 1px,transparent 1px);background-size:34px 34px;mask-image:radial-gradient(circle at 50% 26%,#000,transparent 78%);}
@keyframes drift{0%,100%{transform:translate(0,0) scale(1);}50%{transform:translate(4%,5%) scale(1.08);}}
@keyframes float{0%,100%{transform:translateY(0);}50%{transform:translateY(-15px);}}
@keyframes pageIn{from{opacity:0;transform:translateY(16px);}to{opacity:1;transform:none;}}
@keyframes pop{from{opacity:0;transform:scale(.85);}to{opacity:1;transform:scale(1);}}
.wrap{position:relative;z-index:2;max-width:1120px;margin:0 auto;padding:0 22px;}
.reveal{opacity:0;transform:translateY(26px);transition:opacity .7s cubic-bezier(.2,.7,.2,1),transform .7s cubic-bezier(.2,.7,.2,1);}
.reveal.in{opacity:1;transform:none;}
.page{animation:pageIn .5s cubic-bezier(.2,.7,.2,1);}
/* nav */
.nav{position:sticky;top:0;z-index:60;backdrop-filter:blur(16px) saturate(150%);background:rgba(246,250,254,.78);border-bottom:1px solid var(--line);transition:.3s;}
.nav.scrolled{background:rgba(246,250,254,.94);box-shadow:0 8px 30px -18px rgba(21,39,63,.4);}
.nav-in{max-width:1120px;margin:0 auto;padding:11px 22px;display:flex;align-items:center;gap:18px;}
.brand{display:flex;align-items:center;gap:11px;cursor:pointer;flex:none;transition:.25s;}.brand:hover{opacity:.82;}
.chip{display:flex;align-items:center;justify-content:center;width:42px;height:42px;flex:none;}
.chip img{width:40px;height:40px;object-fit:contain;filter:drop-shadow(0 3px 8px rgba(21,39,63,.22));}
.brand .disp{font-size:24px;line-height:1;background:linear-gradient(120deg,var(--navy),var(--cyan));-webkit-background-clip:text;background-clip:text;color:transparent;}
.brand small{display:block;font-family:'Cormorant Garamond',serif;font-size:12.5px;font-weight:600;letter-spacing:.13em;color:var(--navy);margin-top:1px;}
.nav-links{display:flex;gap:3px;margin-left:auto;overflow-x:auto;scrollbar-width:none;}.nav-links::-webkit-scrollbar{display:none;}
.nlink{position:relative;background:none;border:none;color:var(--muted);font-family:inherit;font-weight:600;font-size:14px;padding:9px 14px;border-radius:10px;cursor:pointer;transition:.22s;white-space:nowrap;}
.nlink:hover{color:var(--navy);}
.nlink.on{color:var(--navy);}
.nlink.on::after{content:"";position:absolute;left:14px;right:14px;bottom:3px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--navy),var(--cyan));animation:pop .35s ease;}
.nlink.admin{margin-left:6px;border:1px solid var(--line2);color:var(--gold);border-radius:9px;}.nlink.admin:hover{background:rgba(184,134,30,.08);}
/* buttons */
.btn{font-family:inherit;font-weight:700;font-size:14px;border-radius:13px;padding:12px 20px;border:1px solid transparent;cursor:pointer;transition:.28s cubic-bezier(.2,.7,.2,1);display:inline-flex;align-items:center;gap:8px;}
.btn-primary{background:linear-gradient(120deg,var(--navy2),var(--cyan));color:#fff;box-shadow:0 12px 28px -12px rgba(30,132,198,.7);}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 18px 38px -12px rgba(30,132,198,.8);}
.btn-ghost{background:#fff;border-color:var(--line2);color:var(--navy);box-shadow:0 4px 14px -10px rgba(21,39,63,.5);}.btn-ghost:hover{background:#fff;border-color:var(--cyan);transform:translateY(-2px);}
.btn-gold{background:linear-gradient(120deg,var(--gold-l),var(--gold));color:#241803;box-shadow:0 12px 26px -14px rgba(184,134,30,.7);}.btn-gold:hover{transform:translateY(-2px);}
.btn-danger{background:#fff;color:var(--loss);border-color:rgba(214,69,92,.35);}.btn-danger:hover{background:rgba(214,69,92,.07);}
.btn-sm{padding:8px 14px;font-size:12.5px;border-radius:10px;}
/* hero */
.hero{min-height:calc(100vh - 64px);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:40px 0 60px;position:relative;}
.crest{position:relative;display:flex;align-items:center;justify-content:center;width:232px;height:232px;animation:float 6.5s ease-in-out infinite;}
.crest::before{content:"";position:absolute;inset:4%;border-radius:50%;background:radial-gradient(circle at 50% 46%,rgba(30,132,198,.22),rgba(26,163,134,.10) 46%,transparent 70%);filter:blur(10px);}
.crest img{position:relative;z-index:1;width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 18px 36px rgba(21,39,63,.28));}
.crest.about{width:206px;height:206px;animation-duration:7s;}
.hero .mark{font-size:clamp(76px,17vw,168px);line-height:.86;margin:14px 0 0;background:linear-gradient(135deg,var(--navy) 24%,var(--cyan) 96%);-webkit-background-clip:text;background-clip:text;color:transparent;}
.hero .full{font-size:13px;letter-spacing:.42em;color:var(--cyan-d);margin-top:14px;font-weight:700;}
.hero-cta{display:flex;gap:12px;margin-top:32px;flex-wrap:wrap;justify-content:center;}
.hero .champ-tag{display:inline-flex;align-items:center;gap:9px;margin-top:30px;font-size:13px;color:var(--muted);background:var(--card);border:1px solid var(--line);padding:8px 16px;border-radius:30px;box-shadow:0 8px 22px -16px rgba(21,39,63,.5);}
.hero .champ-tag b{color:var(--gold);font-weight:800;}
/* 홈 요약 */
.home{padding:46px 0 44px;}
.home-hero{display:flex;flex-direction:column;align-items:center;text-align:center;margin-bottom:38px;}
.crest.small{width:138px;height:138px;}
.home .mark{font-size:clamp(52px,12vw,92px);line-height:.86;margin:10px 0 0;background:linear-gradient(135deg,var(--navy) 24%,var(--cyan) 96%);-webkit-background-clip:text;background-clip:text;color:transparent;}
.home-tag{color:var(--muted);font-size:14px;margin:9px 0 0;font-weight:600;}
.home-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;}
@media(max-width:640px){.home-grid{grid-template-columns:1fr;}}
.hcard{width:100%;text-align:left;background:var(--card);border:1px solid var(--line);border-radius:18px;padding:22px;cursor:pointer;font-family:inherit;box-shadow:0 12px 30px -22px rgba(21,39,63,.35);transition:transform .3s cubic-bezier(.2,.7,.2,1),box-shadow .3s,border-color .3s;}
.hcard:hover{transform:translateY(-4px);border-color:rgba(30,132,198,.4);box-shadow:0 24px 50px -28px rgba(30,132,198,.4);}
.hcard.wide{grid-column:1/-1;}
.hcard-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;}
.hc-kick{font-size:12px;font-weight:800;letter-spacing:.13em;text-transform:uppercase;color:var(--cyan-d);}
.hc-go{color:var(--muted2);font-weight:800;font-size:16px;transition:.25s;}
.hcard:hover .hc-go{color:var(--cyan);transform:translateX(4px);}
.hcard-champ{display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;}
.hc-cur-label{font-size:12.5px;color:var(--gold);font-weight:800;}
.hc-cur-name{font-size:30px;font-weight:800;color:var(--navy);line-height:1.1;margin:3px 0;}
.hc-cur-sub{font-size:12.5px;color:var(--muted);}
.hc-team{display:flex;gap:7px;}
.hc-mon{width:48px;height:48px;border-radius:12px;background:linear-gradient(160deg,#fff,#eaf1f8);border:1px solid var(--line);display:flex;align-items:center;justify-content:center;overflow:hidden;}
.hc-mon img{width:90%;height:90%;object-fit:contain;}
.hc-mon i{font-style:normal;font-weight:800;color:var(--muted2);}
@media(max-width:560px){.hc-mon{width:42px;height:42px;}.hc-cur-name{font-size:26px;}}
.hc-rank{display:flex;flex-direction:column;gap:10px;}
.hc-rrow{display:flex;align-items:center;gap:11px;}
.hc-rname{font-weight:700;color:var(--navy);flex:1;}
.hc-rpts{font-weight:800;color:var(--cyan-d);}
.hc-bignum{font-size:48px;font-weight:800;color:var(--navy);line-height:1;}
.hc-bignum span{font-size:18px;color:var(--muted);margin-left:5px;font-weight:700;}
.hc-sub{font-size:13px;color:var(--muted);margin-top:9px;}
.hc-ndate{font-size:12px;color:var(--muted2);font-weight:700;}
.hc-ntitle{font-size:16px;font-weight:700;color:var(--navy);margin-top:5px;line-height:1.4;}
.hc-empty{font-size:13.5px;color:var(--muted2);padding:6px 0;}
.hc-about{font-size:14px;line-height:1.7;color:var(--muted);}
.hc-about b{color:var(--navy);font-weight:700;}
.scrollcue{position:absolute;bottom:22px;left:50%;transform:translateX(-50%);width:24px;height:38px;border:2px solid var(--line2);border-radius:14px;display:flex;justify-content:center;padding-top:7px;opacity:.7;}
.scrollcue::before{content:"";width:4px;height:8px;border-radius:3px;background:var(--cyan);animation:cue 1.6s ease-in-out infinite;}
@keyframes cue{0%{opacity:0;transform:translateY(-3px);}40%{opacity:1;}100%{opacity:0;transform:translateY(10px);}}
/* sections */
.sec{padding:74px 0 34px;}
.sec-head{margin-bottom:30px;}
.sec-head .kick{font-size:12px;letter-spacing:.26em;text-transform:uppercase;color:var(--cyan-d);font-weight:700;}
.sec-head h2{font-size:clamp(30px,5vw,46px);line-height:1.02;margin:9px 0 0;font-weight:800;letter-spacing:-.02em;color:var(--navy);}
.sec-head .sub{color:var(--muted);font-size:14.5px;line-height:1.6;margin:13px 0 0;max-width:680px;}
.row-actions{display:flex;gap:10px;align-items:center;margin-top:16px;flex-wrap:wrap;}
.grid{display:grid;gap:16px;}.g3{grid-template-columns:repeat(3,1fr);}.g2{grid-template-columns:repeat(2,1fr);}
@media(max-width:840px){.g3{grid-template-columns:repeat(2,1fr);}}@media(max-width:560px){.g3,.g2{grid-template-columns:1fr;}}
.card{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:22px;transition:transform .35s cubic-bezier(.2,.7,.2,1),border-color .35s,box-shadow .35s;box-shadow:0 12px 30px -22px rgba(21,39,63,.35);}
.card.hover:hover{transform:translateY(-5px);border-color:rgba(30,132,198,.4);box-shadow:0 26px 54px -28px rgba(30,132,198,.45);}
.panel{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:8px 18px;box-shadow:0 14px 36px -26px rgba(21,39,63,.4);}
/* about */
.about-hero{display:grid;grid-template-columns:1.3fr 1fr;gap:34px;align-items:center;margin-bottom:18px;}
@media(max-width:780px){.about-hero{grid-template-columns:1fr;}}
.about-hero .lead{font-size:clamp(19px,2.6vw,24px);line-height:1.6;font-weight:600;color:var(--navy);}
.about-hero .lead .hl{background:linear-gradient(120deg,var(--cyan-d),var(--mint));-webkit-background-clip:text;background-clip:text;color:transparent;font-weight:800;}
.about-hero .logo-wrap{display:flex;justify-content:center;}
.kick-line{display:block;font-size:13px;letter-spacing:.24em;text-transform:uppercase;color:var(--cyan-d);font-weight:700;}
.timeline{position:relative;margin:14px 0 6px;padding-left:30px;}
.timeline::before{content:"";position:absolute;left:7px;top:6px;bottom:6px;width:2px;background:linear-gradient(180deg,var(--navy),var(--cyan),transparent);}
.tl-item{position:relative;padding:0 0 26px;}
.tl-item::before{content:"";position:absolute;left:-30px;top:4px;width:16px;height:16px;border-radius:50%;background:#fff;border:3px solid var(--cyan);box-shadow:0 0 0 4px rgba(30,132,198,.12);}
.tl-item:last-child::before{border-color:var(--mint);box-shadow:0 0 0 4px rgba(26,163,134,.14);}
.tl-date{font-size:12.5px;font-weight:800;color:var(--cyan-d);letter-spacing:.04em;}
.tl-title{font-size:18px;font-weight:800;margin:3px 0 6px;color:var(--navy);}
.tl-body{color:var(--muted);font-size:14px;line-height:1.65;}
.comp{position:relative;overflow:hidden;}
.comp .ribbon{font-size:11px;font-weight:800;letter-spacing:.04em;padding:4px 11px;border-radius:20px;display:inline-block;}
.comp .comp-top{height:50px;display:flex;align-items:center;}
.comp h3{margin:11px 0 2px;font-size:20px;font-weight:800;color:var(--navy);}
.comp .en{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted2);}
.comp p{color:var(--muted);font-size:13.5px;line-height:1.65;margin:13px 0 0;}
.comp img{width:46px;height:46px;object-fit:contain;}
.comp .glow{position:absolute;top:-44px;right:-44px;width:130px;height:130px;border-radius:50%;filter:blur(36px);opacity:.4;}
/* 정규 리그 — 로고 중심 그라데이션 카드 */
.lg2{position:relative;border-radius:24px;padding:38px 30px 32px;text-align:center;overflow:hidden;color:#fff;box-shadow:0 24px 54px -26px rgba(21,39,63,.55);transition:transform .4s cubic-bezier(.2,.7,.2,1),box-shadow .4s;}
.lg2:hover{transform:translateY(-6px);box-shadow:0 36px 70px -28px rgba(21,39,63,.6);}
.lg2.master{background:linear-gradient(150deg,#16273F 0%,#1E5C92 55%,#2E9BDC 110%);}
.lg2.rookie{background:linear-gradient(150deg,#0F5246 0%,#179C7E 55%,#54CFB1 115%);}
.lg2 .lg2-glow{position:absolute;top:-60px;right:-60px;width:220px;height:220px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.22),transparent 70%);}
.lg2 .lg2-logo{position:relative;width:158px;height:158px;margin:0 auto;border-radius:50%;background:#fff;display:flex;align-items:center;justify-content:center;box-shadow:0 18px 40px -14px rgba(0,0,0,.4),0 0 0 8px rgba(255,255,255,.14);}
.lg2 .lg2-logo img{width:124px;height:124px;object-fit:contain;}
.lg2 .lg2-tier{display:inline-block;margin-top:22px;font-size:11.5px;font-weight:800;letter-spacing:.1em;padding:5px 14px;border-radius:30px;background:rgba(255,255,255,.18);color:#fff;backdrop-filter:blur(4px);}
.lg2 h3{margin:13px 0 2px;font-size:28px;font-weight:800;color:#fff;letter-spacing:-.01em;}
.lg2 .en{font-size:11px;letter-spacing:.24em;text-transform:uppercase;color:rgba(255,255,255,.72);}
.lg2 p{color:rgba(255,255,255,.92);font-size:14px;line-height:1.7;margin:16px auto 0;max-width:330px;}
/* champions */
.champ{position:relative;overflow:hidden;border-radius:18px;padding:22px;border:1px solid var(--line);background:linear-gradient(155deg,rgba(214,166,58,.14),#fff 60%);box-shadow:0 14px 34px -24px rgba(184,134,30,.5);transition:transform .35s cubic-bezier(.2,.7,.2,1),box-shadow .35s;}
.champ.hover:hover{transform:translateY(-5px);box-shadow:0 26px 54px -26px rgba(184,134,30,.55);}
.champ .crown{position:absolute;top:-28px;right:-18px;font-size:120px;opacity:.08;}
.champ .gen{font-size:12.5px;letter-spacing:.06em;color:var(--gold);font-weight:800;}
.champ .nm{font-size:27px;font-weight:800;margin:3px 0 15px;color:var(--navy);}
.team{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;margin-top:6px;}
.poke{display:flex;flex-direction:column;align-items:center;}
.poke .sp{width:100%;aspect-ratio:1/1;border-radius:15px;background:linear-gradient(160deg,#ffffff,#eaf1f8);border:1px solid var(--line);display:flex;align-items:center;justify-content:center;overflow:hidden;transition:transform .25s cubic-bezier(.2,.7,.2,1),box-shadow .25s,border-color .25s;}
.poke:hover .sp{transform:translateY(-4px);box-shadow:0 16px 30px -16px rgba(30,132,198,.5);border-color:rgba(30,132,198,.45);}
.poke img{width:90%;height:90%;object-fit:contain;}
.poke .pn{margin-top:7px;font-size:11.5px;font-weight:700;color:var(--navy);text-align:center;line-height:1.25;}
.poke.noimg .sp{background:rgba(21,39,63,.045);}
.poke.noimg .ph{font-size:11.5px;font-weight:700;color:var(--muted2);text-align:center;padding:6px;line-height:1.3;}
/* titles */
.tgroup{margin-bottom:42px;}
.tgroup-head{display:flex;align-items:center;gap:11px;margin-bottom:16px;flex-wrap:wrap;}
.tgroup-head .ic{font-size:24px;}.tgroup-head h3{margin:0;font-size:22px;font-weight:800;color:var(--navy);}
.tgroup-head .cnt{font-size:12px;color:var(--cyan-d);background:rgba(30,132,198,.10);padding:4px 10px;border-radius:8px;font-weight:700;}
.tgroup-head .gdesc{color:var(--muted);font-size:13px;flex:1;min-width:220px;}
.titem{background:var(--card);border:1px solid var(--line);border-radius:15px;padding:16px 17px;transition:.3s cubic-bezier(.2,.7,.2,1);box-shadow:0 10px 26px -22px rgba(21,39,63,.4);}
.titem:hover{border-color:rgba(30,132,198,.35);transform:translateY(-3px);box-shadow:0 18px 40px -26px rgba(30,132,198,.4);}
.titem.empty{opacity:.5;box-shadow:none;}
.titem .tn{font-weight:800;font-size:15.5px;color:var(--navy);}.titem .td{color:var(--muted);font-size:12px;margin-top:4px;line-height:1.5;}
.titem .hold{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px;}
.holder{font-size:12.5px;font-weight:700;padding:5px 11px;border-radius:9px;background:rgba(184,134,30,.12);color:var(--gold);border:1px solid rgba(184,134,30,.28);}
.holder.mon-h{background:rgba(30,132,198,.11);color:var(--cyan-d);border-color:rgba(30,132,198,.28);}
.none{color:var(--muted2);font-size:12px;font-style:italic;}
/* tables */
.tbl{width:100%;border-collapse:collapse;}
.tbl th{text-align:left;font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted2);padding:13px;border-bottom:2px solid var(--line);white-space:nowrap;font-weight:800;}
.tbl td{padding:13px;border-bottom:1px solid rgba(21,39,63,.06);font-size:14.5px;}
.tbl tbody tr{transition:.18s;}.tbl tbody tr:hover{background:rgba(30,132,198,.05);}
.tbl tr:last-child td{border-bottom:none;}
.tbl td.c,.tbl th.c{text-align:center;}
.rankb{display:inline-flex;width:28px;height:28px;align-items:center;justify-content:center;border-radius:9px;font-weight:800;font-size:13px;background:rgba(21,39,63,.06);color:var(--muted);}
.rankb.r1{background:linear-gradient(135deg,#f0c860,#d09e2e);color:#241803;box-shadow:0 4px 12px -5px rgba(184,134,30,.7);}
.rankb.r2{background:linear-gradient(135deg,#dde6f1,#aebccf);color:#1a2433;}
.rankb.r3{background:linear-gradient(135deg,#e0a36a,#bb7b42);color:#241803;}
.pts{font-weight:800;color:var(--cyan-d);}
/* sub-tabs */
.subtabs{display:inline-flex;gap:4px;background:rgba(21,39,63,.05);border:1px solid var(--line);padding:5px;border-radius:14px;margin-bottom:20px;flex-wrap:wrap;}
.subtab{background:none;border:none;color:var(--muted);font-family:inherit;font-weight:700;font-size:13px;padding:9px 15px;border-radius:10px;cursor:pointer;transition:.25s;white-space:nowrap;}
.subtab:hover{color:var(--navy);}
.subtab.on{color:#fff;background:linear-gradient(120deg,var(--navy2),var(--cyan));box-shadow:0 8px 18px -8px rgba(30,132,198,.6);}
.swap{animation:pageIn .4s cubic-bezier(.2,.7,.2,1);}
/* 전체 회차 */
.round2{display:grid;grid-template-columns:84px 1fr;gap:14px;padding:15px 4px;border-bottom:1px solid rgba(21,39,63,.06);transition:.18s;}
.round2:hover{background:rgba(30,132,198,.04);}
.round2:last-child{border-bottom:none;}
.r2-date{font-size:12.5px;color:var(--muted);font-weight:700;padding-top:3px;}
.r2-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;}
.r2-comp{font-size:11px;font-weight:800;letter-spacing:.02em;padding:3px 10px;border-radius:20px;}
.r2-round{font-size:13px;font-weight:800;color:var(--navy);}
.r2-rule{font-size:11.5px;color:var(--muted2);font-weight:600;}
.r2-mode{font-size:10px;font-weight:800;letter-spacing:.04em;padding:2px 8px;border-radius:20px;background:rgba(184,134,30,.14);color:var(--gold);}
.r2-res{display:flex;flex-wrap:wrap;gap:6px;align-items:center;}
.r2-rk{font-size:10.5px;font-weight:800;color:var(--muted2);letter-spacing:.02em;margin-left:4px;}
.r2-rk:first-child{margin-left:0;}
.r2-rk.gold{color:var(--gold);}
.r2-name{font-size:13px;font-weight:600;padding:4px 10px;border-radius:8px;background:rgba(21,39,63,.05);border:1px solid var(--line);color:var(--navy);}
.r2-name.win{background:linear-gradient(120deg,rgba(236,193,92,.18),rgba(236,193,92,.08));border-color:rgba(184,134,30,.3);color:var(--gold);font-weight:800;}
.r2-name.mem{font-size:11.5px;padding:3px 8px;background:rgba(30,132,198,.07);border-color:rgba(30,132,198,.18);color:var(--cyan-d);font-weight:600;}
.round2.champ{background:linear-gradient(90deg,rgba(236,193,92,.11),rgba(236,193,92,0) 72%);box-shadow:inset 3px 0 0 rgba(184,134,30,.42);border-radius:0 7px 7px 0;}
.round2.champ:hover{background:linear-gradient(90deg,rgba(236,193,92,.18),rgba(236,193,92,.03) 72%);}
.r2-champ{font-size:10px;font-weight:800;letter-spacing:.04em;padding:2px 9px;border-radius:20px;background:linear-gradient(120deg,rgba(236,193,92,.3),rgba(236,193,92,.14));color:var(--gold);border:1px solid rgba(184,134,30,.32);}
/* news */
.ann{display:flex;gap:18px;padding:20px 0;border-bottom:1px solid var(--line);}.ann:last-child{border-bottom:none;}
.ann .date{font-size:12.5px;color:var(--muted2);white-space:nowrap;padding-top:4px;font-weight:700;}
.ann h3{margin:0 0 7px;font-size:18px;font-weight:800;color:var(--navy);}.ann p{margin:0;color:var(--muted);line-height:1.7;font-size:14.5px;white-space:pre-wrap;}
.pin{font-size:10px;font-weight:800;letter-spacing:.06em;color:var(--cyan-d);margin-left:9px;background:rgba(30,132,198,.13);padding:3px 8px;border-radius:6px;vertical-align:middle;}
/* admin / misc */
.admin-bar{position:sticky;top:65px;z-index:55;background:rgba(184,134,30,.1);border-bottom:1px solid rgba(184,134,30,.3);backdrop-filter:blur(8px);}
.admin-bar-in{max-width:1120px;margin:0 auto;padding:10px 22px;font-size:13px;color:var(--gold);font-weight:800;}
.edit-row{display:flex;gap:7px;margin-top:13px;}.ed-pencil{margin-left:auto;}
.toast{position:fixed;bottom:28px;left:50%;transform:translateX(-50%);z-index:200;background:var(--navy);border:1px solid var(--navy2);color:#fff;font-weight:700;padding:13px 24px;border-radius:14px;box-shadow:0 22px 50px -16px rgba(21,39,63,.6);font-size:14px;animation:pop .3s ease;}
.overlay{position:fixed;inset:0;z-index:100;background:rgba(13,27,46,.4);backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center;padding:20px;animation:pageIn .25s ease;}
.modal{width:100%;max-width:560px;background:#fff;border:1px solid var(--line2);border-radius:20px;padding:28px;max-height:88vh;overflow:auto;box-shadow:0 40px 90px -28px rgba(21,39,63,.5);animation:pop .3s cubic-bezier(.2,.7,.2,1);}
.modal h3{margin:0 0 4px;font-size:22px;font-weight:800;color:var(--navy);}.modal .hint{color:var(--muted);font-size:13px;margin:0 0 18px;line-height:1.5;}
.field{margin-bottom:15px;}.field label{display:block;font-size:11.5px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;margin-bottom:7px;}
.field input,.field textarea{width:100%;background:var(--bg2);border:1px solid var(--line);border-radius:11px;padding:12px 14px;color:var(--text);font-family:inherit;font-size:14px;resize:vertical;transition:.2s;}
.field input:focus,.field textarea:focus{outline:none;border-color:var(--cyan);background:#fff;}.field textarea{min-height:84px;line-height:1.5;}
.modal-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:22px;}
/* 간편 편집 그리드 */
.ed-scroll{max-height:46vh;overflow-y:auto;padding-right:4px;margin:0 -2px;}
.ed-grid{display:grid;grid-template-columns:1fr 56px 56px 50px 64px 30px;gap:7px;align-items:center;margin-bottom:7px;}
.ed-grid.ed-head{margin-bottom:9px;}
.ed-grid.ed-head span{font-size:10.5px;font-weight:700;color:var(--muted2);text-transform:uppercase;letter-spacing:.04em;text-align:center;}
.ed-grid.ed-head span:first-child{text-align:left;padding-left:4px;}
.ed-grid input{background:var(--bg2);border:1px solid var(--line);border-radius:9px;padding:9px 10px;color:var(--text);font-family:inherit;font-size:13.5px;width:100%;}
.ed-grid input:focus{outline:none;border-color:var(--cyan);background:#fff;}
.ed-grid input[type=number]{text-align:center;padding:9px 4px;}
.ed-del{background:rgba(214,69,92,.1);border:1px solid rgba(214,69,92,.25);color:var(--loss);border-radius:9px;width:30px;height:34px;cursor:pointer;font-size:13px;font-weight:700;display:flex;align-items:center;justify-content:center;flex:none;}
.ed-del:hover{background:rgba(214,69,92,.2);}
.ed-round{background:var(--bg2);border:1px solid var(--line);border-radius:13px;padding:13px;margin-bottom:11px;display:flex;flex-direction:column;gap:8px;}
.ed-round input{background:#fff;border:1px solid var(--line);border-radius:9px;padding:10px 11px;color:var(--text);font-family:inherit;font-size:13.5px;width:100%;}
.ed-round input:focus{outline:none;border-color:var(--cyan);}
.ed-rtop{display:flex;gap:8px;align-items:center;}
.ed-rtop .ed-w{flex:1;}
.ed-r2{display:grid;grid-template-columns:1fr 1fr;gap:8px;}
.ed-seg{display:inline-flex;background:rgba(21,39,63,.05);border:1px solid var(--line);border-radius:9px;padding:3px;gap:3px;align-self:flex-start;}
.ed-seg button{border:none;background:transparent;color:var(--muted);font-family:inherit;font-size:12.5px;font-weight:700;padding:6px 16px;border-radius:7px;cursor:pointer;transition:.2s;}
.ed-seg button.on{background:#fff;color:var(--navy);box-shadow:0 2px 8px -4px rgba(21,39,63,.4);}
.ed-mv{background:rgba(21,39,63,.05);border:1px solid var(--line);color:var(--muted);border-radius:9px;width:30px;height:34px;cursor:pointer;font-size:11px;font-weight:700;display:flex;align-items:center;justify-content:center;flex:none;}
.ed-mv:hover:not(:disabled){background:rgba(30,132,198,.12);color:var(--cyan-d);}
.ed-mv:disabled{opacity:.3;cursor:default;}
.ed-auto{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;font-weight:700;color:var(--muted);cursor:pointer;user-select:none;}
.ed-auto input{width:15px;height:15px;accent-color:var(--cyan);cursor:pointer;}
.ed-team{display:flex;flex-direction:column;gap:6px;padding:10px;border-radius:10px;background:rgba(255,255,255,.6);border:1px solid var(--line);}
.ed-rk{font-size:11.5px;font-weight:800;color:var(--muted2);display:flex;align-items:center;gap:8px;}
.ed-rk.gold{color:var(--gold);}
.ed-x{background:none;border:none;color:var(--loss);cursor:pointer;font-size:12px;font-weight:700;padding:0 4px;}
.pts-note{font-size:12px;line-height:1.6;color:var(--muted);background:rgba(184,134,30,.07);border:1px solid rgba(184,134,30,.2);border-radius:10px;padding:10px 13px;}
.pts-note b{color:var(--gold);font-weight:800;}
.footer{padding:48px 0 56px;color:var(--muted2);font-size:12.5px;border-top:1px solid var(--line);margin-top:40px;line-height:1.8;}
.footer b{color:var(--muted);}
`;

/* ============================== 모션 헬퍼 ============================== */
function Reveal({ children, delay=0, className="", tag="div", ...rest }) {
  const ref=useRef(null); const [seen,setSeen]=useState(false);
  useEffect(()=>{const el=ref.current;if(!el)return;
    const io=new IntersectionObserver(([e])=>{if(e.isIntersecting){setSeen(true);io.disconnect();}},{threshold:.12,rootMargin:"0px 0px -40px 0px"});
    io.observe(el);return()=>io.disconnect();},[]);
  const Tag=tag;
  return <Tag ref={ref} className={`reveal ${seen?"in":""} ${className}`} style={{transitionDelay:delay+"ms"}} {...rest}>{children}</Tag>;
}
function CountUp({ to, dur=1100, suffix="" }) {
  const [v,setV]=useState(0); const ref=useRef(null); const done=useRef(false);
  useEffect(()=>{const el=ref.current;if(!el)return;
    const io=new IntersectionObserver(([e])=>{if(e.isIntersecting&&!done.current){done.current=true;
      const t0=performance.now();const step=(t)=>{const p=Math.min(1,(t-t0)/dur);setV(Math.round(to*(1-Math.pow(1-p,3))));if(p<1)requestAnimationFrame(step);};requestAnimationFrame(step);io.disconnect();}},{threshold:.5});
    io.observe(el);return()=>io.disconnect();},[to,dur]);
  return <span ref={ref} className="tnum">{v}{suffix}</span>;
}

/* ============================== 공통 ============================== */
function Modal({ title, hint, children, onClose }) {
  return <div className="overlay" onClick={onClose}><div className="modal" onClick={(e)=>e.stopPropagation()}><h3>{title}</h3>{hint&&<p className="hint">{hint}</p>}{children}</div></div>;
}
function StandTable({ rows, showNote }) {
  const sorted=[...rows].sort((a,b)=>(b.points||0)-(a.points||0));
  return (<table className="tbl tnum"><thead><tr>
    <th style={{width:56}}>순위</th><th>트레이너</th><th className="c" style={{width:62}}>우승</th><th className="c" style={{width:66}}>준우승</th><th className="c" style={{width:54}}>4강</th><th className="c" style={{width:72}}>포인트</th>{showNote&&<th style={{width:96}}>비고</th>}
  </tr></thead><tbody>{sorted.map((r,i)=>(<tr key={i}>
    <td><span className={"rankb "+(i<3?"r"+(i+1):"")}>{i+1}</span></td>
    <td style={{fontWeight:700,fontVariantNumeric:"normal"}}>{r.name}</td>
    <td className="c">{r.win||0}</td><td className="c">{r.ru||0}</td><td className="c">{r.top4||0}</td>
    <td className="c pts">{r.points||0}</td>{showNote&&<td style={{color:"var(--muted)",fontSize:12.5}}>{r.note||""}</td>}
  </tr>))}</tbody></table>);
}
const ACC={cyan:"var(--cyan)",mint:"var(--mint)",gold:"var(--gold)"};
const ACC_BG={cyan:"rgba(59,182,236,.13)",mint:"rgba(84,207,177,.13)",gold:"rgba(236,193,92,.13)"};

/* ============================== 앱 ============================== */
export default function App() {
  const [data,setData]=useState(null); const [view,setView]=useState("home");
  const [admin,setAdmin]=useState(false); const [toast,setToast]=useState(""); const [modal,setModal]=useState(null);
  const [scrolled,setScrolled]=useState(false);
  useEffect(()=>{(async()=>setData((await loadData())||SEED))();},[]);
  useEffect(()=>{const f=()=>setScrolled(window.scrollY>20);window.addEventListener("scroll",f);return()=>window.removeEventListener("scroll",f);},[]);
  const go=useCallback((v)=>{setView(v);window.scrollTo({top:0,behavior:"smooth"});},[]);
  const flash=useCallback((m)=>{setToast(m);setTimeout(()=>setToast(""),1800);},[]);
  const save=useCallback(async(next)=>{setData(next);const ok=await persist(next);flash(ok?"저장됨 ✓":"메모리에만 반영됨");},[flash]);
  if(!data) return <div className="ypl" style={{display:"flex",alignItems:"center",justifyContent:"center",minHeight:"60vh"}}><style>{STYLES}</style><span style={{color:"#90A1BD"}}>불러오는 중…</span></div>;
  const nav=[["about","소개"],["news","공지"],["records","기록"],["titles","칭호"],["champions","명예의 전당"]];
  return (
    <div className="ypl"><style>{STYLES}</style>
      <div className="aurora"><i className="a1"/><i className="a2"/><i className="a3"/><div className="grid"/></div>
      <nav className={"nav"+(scrolled?" scrolled":"")}><div className="nav-in">
        <div className="brand" onClick={()=>go("home")}><span className="chip"><img src={LOGO_YPL} alt="YPL"/></span><div><span className="disp">YPL</span><small>POKÉMON · CENTER · YONSEI</small></div></div>
        <div className="nav-links">{nav.map(([k,l])=><button key={k} className={"nlink"+(view===k?" on":"")} onClick={()=>go(k)}>{l}</button>)}
          <button className="nlink admin" onClick={()=>admin?setAdmin(false):setModal({type:"login"})}>{admin?"로그아웃":"관리자"}</button></div>
      </div></nav>
      {admin&&<div className="admin-bar"><div className="admin-bar-in">⚙ 관리자 모드 — 각 섹션에서 추가·수정·삭제할 수 있습니다.</div></div>}

      <div className="wrap"><div className="page" key={view}>
        {view==="home"&&<Home data={data} go={go}/>}
        {view==="about"&&<About/>}
        {view==="news"&&<News data={data} admin={admin} setModal={setModal}/>}
        {view==="records"&&<Records data={data} admin={admin} setModal={setModal} save={save}/>}
        {view==="titles"&&<Titles data={data} admin={admin} setModal={setModal}/>}
        {view==="champions"&&<Champions data={data} admin={admin} setModal={setModal}/>}
      </div>
      {view!=="home"&&<footer className="footer"><b>{data.meta.fullName}</b> · {data.meta.tagline}<br/>© {new Date().getFullYear()} 포켓몬 센터 연세점 (포센연). 동아리 자체 리그 기록 사이트.</footer>}
      </div>
      {toast&&<div className="toast">{toast}</div>}

      {modal?.type==="login"&&<LoginModal onClose={()=>setModal(null)} onSuccess={()=>{setAdmin(true);setModal(null);flash("관리자 로그인 ✓");}}/>}
      {modal?.type==="meta"&&<MetaEditor meta={data.meta} onClose={()=>setModal(null)} onSave={(meta)=>{save({...data,meta});setModal(null);}}/>}
      {modal?.type==="champion"&&<ChampionEditor item={modal.item} onClose={()=>setModal(null)} onSave={(c)=>{const champions=modal.item?data.champions.map(x=>x.id===c.id?c:x):[...data.champions,c];save({...data,champions});setModal(null);}} onDelete={modal.item?()=>{save({...data,champions:data.champions.filter(x=>x.id!==modal.item.id)});setModal(null);}:null}/>}
      {modal?.type==="title"&&<TitleItemEditor groupKey={modal.groupKey} item={modal.item} onClose={()=>setModal(null)} onSave={(it)=>{const titleGroups=data.titleGroups.map(g=>g.key!==modal.groupKey?g:{...g,items:modal.item?g.items.map(x=>x.id===it.id?it:x):[...g.items,it]});save({...data,titleGroups});setModal(null);}} onDelete={modal.item?()=>{const titleGroups=data.titleGroups.map(g=>g.key!==modal.groupKey?g:{...g,items:g.items.filter(x=>x.id!==modal.item.id)});save({...data,titleGroups});setModal(null);}:null}/>}
      {modal?.type==="ann"&&<AnnEditor item={modal.item} onClose={()=>setModal(null)} onSave={(a)=>{const announcements=modal.item?data.announcements.map(x=>x.id===a.id?a:x):[a,...data.announcements];save({...data,announcements});setModal(null);}} onDelete={modal.item?()=>{save({...data,announcements:data.announcements.filter(x=>x.id!==modal.item.id)});setModal(null);}:null}/>}
      {modal?.type==="standings"&&<StandingsEditor title={modal.title} rows={modal.rows} onClose={()=>setModal(null)} onSave={(rows)=>{save(modal.build(rows));setModal(null);}}/>}
      {modal?.type==="rounds"&&<RoundsEditor title={modal.title} rounds={modal.rounds} simple={modal.simple} onClose={()=>setModal(null)} onSave={(rounds)=>{save(modal.build(rounds));setModal(null);}}/>}
    </div>
  );
}

/* ============================== HOME ============================== */
function Home({ data, go }) {
  const eras=data.rankings||[];
  const ypl=eras.find(e=>e.key==="era2")||eras[0];
  const top3=ypl?[...ypl.rows].sort((a,b)=>(b.points||0)-(a.points||0)).slice(0,3):[];
  const champs=[...data.champions].sort((a,b)=>b.season-a.season);
  const cur=champs[0];
  const titleCount=data.titleGroups.reduce((n,g)=>n+g.items.length,0);
  const awarded=useMemo(()=>{const s=new Set();data.titleGroups.forEach(g=>g.items.forEach(it=>(it.holders||[]).forEach(h=>s.add(h))));return s.size;},[data]);
  const news=[...data.announcements].sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||(a.date<b.date?1:-1))[0];
  return (<section className="home">
    <Reveal className="home-hero">
      <h1 className="disp mark">YPL</h1>
      <p className="home-tag">{data.meta.tagline}</p>
    </Reveal>
    <div className="home-grid">
      <Reveal tag="button" className="hcard wide" onClick={()=>go("champions")}>
        <div className="hcard-head"><span className="hc-kick">명예의 전당</span><span className="hc-go">→</span></div>
        <div className="hcard-champ">
          <div><div className="hc-cur-label">👑 현 챔피언 · {cur?.gen}</div>
            <div className="hc-cur-name">{cur?.name}</div>
            <div className="hc-cur-sub">{champs.length}명의 역대 챔피언</div></div>
          {cur&&<div className="hc-team">{cur.team.filter(Boolean).slice(0,6).map((m,i)=>{const img=POKE_IMG[m];return <span className="hc-mon" key={i}>{img?<img src={img} alt={m}/>:<i>{m[0]}</i>}</span>;})}</div>}
        </div>
      </Reveal>
      <Reveal tag="button" className="hcard" delay={60} onClick={()=>go("records")}>
        <div className="hcard-head"><span className="hc-kick">기록 · YPL 랭킹</span><span className="hc-go">→</span></div>
        <div className="hc-rank">{top3.map((r,i)=>(
          <div className="hc-rrow" key={i}><span className={"rankb "+(i<3?"r"+(i+1):"")}>{i+1}</span><span className="hc-rname">{r.name}</span><span className="hc-rpts tnum">{r.points}</span></div>))}
          {top3.length===0&&<div className="hc-empty">데이터 없음</div>}</div>
      </Reveal>
      <Reveal tag="button" className="hcard" delay={120} onClick={()=>go("titles")}>
        <div className="hcard-head"><span className="hc-kick">칭호</span><span className="hc-go">→</span></div>
        <div className="hc-bignum tnum">{titleCount}<span>개</span></div>
        <div className="hc-sub">트레이너 {awarded}명이 칭호 보유 중</div>
      </Reveal>
      <Reveal tag="button" className="hcard wide" delay={60} onClick={()=>go("news")}>
        <div className="hcard-head"><span className="hc-kick">공지</span><span className="hc-go">→</span></div>
        {news?<div className="hc-news"><div className="hc-ndate tnum">{news.date}</div><div className="hc-ntitle">{news.title}</div></div>:<div className="hc-empty">새 공지가 없습니다.</div>}
      </Reveal>
    </div>
  </section>);
}

/* ============================== ABOUT ============================== */
function About() {
  const logoFor=(k)=>k==="rookie"?LOGO_ROOKIE:k==="master"?LOGO_MASTER:null;
  return (<section className="sec">
    <Reveal className="sec-head"><div className="kick">About</div><h2>YPL 이야기</h2>
      <p className="sub">연세대학교 포켓몬스터 동아리인 포켓몬 센터 연세점, 일명 포센연에서 시작된 배틀 리그의 발자취입니다.</p>
    </Reveal>
    <div className="about-hero">
      <Reveal><p className="lead">YPL은 포센연 내에서 자체적으로 치러진 대회, <span className="hl">PY-CUP</span>에서 시작되었습니다. 2023년 5월의 첫 대회 이후 매월의 도전이 쌓여, 2025년 6월 마스터 리그와 루키 리그로의 양분화라는 <span className="hl">대격변</span>을 거쳐 지금의 YPL 체제가 확립되었습니다.</p></Reveal>
      <Reveal className="logo-wrap" delay={120}><div className="crest about"><img src={LOGO_YPL} alt="YPL"/></div></Reveal>
    </div>

    <Reveal tag="h3" className="" delay={0}><span className="kick-line" style={{margin:"40px 0 18px"}}>연혁</span></Reveal>
    <div className="timeline">{TIMELINE.map((t,i)=>(
      <Reveal key={i} className="tl-item" delay={i*90}>
        <div className="tl-date">{t.date}</div><div className="tl-title">{t.title}</div><div className="tl-body">{t.body}</div>
      </Reveal>))}</div>

    <Reveal tag="h3"><span className="kick-line" style={{margin:"44px 0 18px"}}>대회</span></Reveal>
    <div className="grid g3">{COMPS.map((c,i)=>(
      <Reveal key={i} className="card hover comp" delay={i*70}>
        <div className="glow" style={{background:ACC[c.accent]}}/>
        <div className="comp-top"><span className="ribbon" style={{background:ACC_BG[c.accent],color:ACC[c.accent]}}>{c.tag}</span></div>
        <h3>{c.name}</h3><div className="en">{c.en}</div><p>{c.desc}</p>
      </Reveal>))}</div>

    <Reveal tag="h3"><span className="kick-line" style={{margin:"48px 0 8px"}}>정규 리그</span></Reveal>
    <Reveal tag="p" className="sub" style={{margin:"0 0 20px",color:"var(--muted)",fontSize:14}}>2025년 6월 양분화 이후, YPL은 두 개의 정규 리그 체제로 운영됩니다.</Reveal>
    <div className="grid g2">{LEAGUES2.map((lg,i)=>{const logo=logoFor(lg.logo);return (
      <Reveal key={i} className={"lg2 "+lg.logo} delay={i*90}>
        <div className="lg2-glow"/>
        <div className="lg2-logo"><img src={logo} alt={lg.name}/></div>
        <span className="lg2-tier">{lg.tier}</span>
        <h3>{lg.name}</h3><div className="en">{lg.en}</div><p>{lg.desc}</p>
      </Reveal>);})}</div>
  </section>);
}

/* ============================== NEWS ============================== */
function News({ data, admin, setModal }) {
  const list=[...data.announcements].sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||(a.date<b.date?1:-1));
  return (<section className="sec">
    <Reveal className="sec-head"><div className="kick">Announcements</div><h2>공지</h2>
      <p className="sub">대회 일정과 리그 운영 소식을 안내합니다.</p>
      {admin&&<div className="row-actions"><button className="btn btn-gold btn-sm" onClick={()=>setModal({type:"ann"})}>+ 공지 작성</button></div>}
    </Reveal>
    <Reveal className="panel" style={{padding:"4px 24px"}}>
      {list.length===0&&<div style={{padding:"40px 0",textAlign:"center",color:"var(--muted2)",fontSize:14}}>등록된 공지가 없습니다.</div>}
      {list.map(a=>(<div className="ann" key={a.id}>
      <div className="date">{a.date}</div><div style={{flex:1}}><h3>{a.title}{a.pinned&&<span className="pin">고정</span>}</h3><p>{a.body}</p>
      {admin&&<div className="edit-row"><button className="btn btn-ghost btn-sm" onClick={()=>setModal({type:"ann",item:a})}>수정</button></div>}</div></div>))}
    </Reveal>
  </section>);
}

/* ============================== RECORDS ============================== */
function Records({ data, admin, setModal, save }) {
  const [tab,setTab]=useState("rank");
  return (<section className="sec">
    <Reveal className="sec-head"><div className="kick">Records &amp; Stats</div><h2>기록</h2>
      <p className="sub">YPL의 모든 전적입니다.</p>
    </Reveal>
    <Reveal className="subtabs">{[["rank","누적 랭킹"],["season","시즌별 성적"],["tour","대회 회차"]].map(([k,l])=>
      <button key={k} className={"subtab"+(tab===k?" on":"")} onClick={()=>setTab(k)}>{l}</button>)}
    </Reveal>
    <Reveal tag="p" className="pts-note" style={{margin:"0 0 16px"}}>우승 <b>60</b>점, 준우승 <b>40</b>점, 4강 <b>20</b>점이 기본 포인트 기준입니다. 팀전 여부, 팀원 수, 대회 사정에 따라 변동될 수 있습니다.</Reveal>
    <div className="swap" key={tab}>
      {tab==="rank"&&<RankView data={data} admin={admin} setModal={setModal}/>}
      {tab==="season"&&<SeasonView data={data} admin={admin} setModal={setModal}/>}
      {tab==="tour"&&<TourView data={data} admin={admin} setModal={setModal}/>}
    </div>
  </section>);
}
function RankView({ data, admin, setModal }) {
  const eras=data.rankings||[]; const [sel,setSel]=useState(eras[0]?.key);
  const era=eras.find(e=>e.key===sel)||eras[0];
  if(!era) return <div className="panel none" style={{padding:24}}>데이터 없음</div>;
  return (<>
    <div className="subtabs">{eras.map(e=><button key={e.key} className={"subtab"+(e.key===sel?" on":"")} onClick={()=>setSel(e.key)}>{e.label}</button>)}</div>
    <div className="panel swap" key={sel}>
      {admin&&<div style={{padding:"12px 0 2px"}}><button className="btn btn-gold btn-sm" onClick={()=>setModal({type:"standings",title:era.label+" 랭킹",rows:era.rows,build:(rows)=>({...data,rankings:eras.map(x=>x.key===era.key?{...x,rows}:x)})})}>이 시기 랭킹 수정</button></div>}
      <StandTable rows={era.rows}/>
    </div>
  </>);
}
function SeasonView({ data, admin, setModal }) {
  const seasons=data.seasons||[]; const [sel,setSel]=useState(0);
  const s=seasons[sel]; if(!s) return <div className="panel none" style={{padding:24}}>데이터 없음</div>;
  const hasNote=s.rows.some(r=>r.note);
  return (<>
    <div className="subtabs">{seasons.map((x,i)=><button key={i} className={"subtab"+(i===sel?" on":"")} onClick={()=>setSel(i)}>{x.name}</button>)}</div>
    <div className="panel swap" key={sel}>
      {admin&&<div style={{padding:"12px 0 2px"}}><button className="btn btn-gold btn-sm" onClick={()=>setModal({type:"standings",title:s.name,rows:s.rows,build:(rows)=>({...data,seasons:seasons.map((x,i)=>i===sel?{...x,rows}:x)})})}>{s.name} 성적 수정</button></div>}
      <StandTable rows={s.rows} showNote={hasNote}/>
    </div>
  </>);
}
function NameChips({ list, kind }) {
  return <>{list.map((n,i)=><span key={i} className={"r2-name "+(kind||"")}>{n}</span>)}</>;
}
function TourView({ data, admin, setModal }) {
  const tours=data.tournaments||[];
  const [sel,setSel]=useState(tours[0]?.key);
  const t=tours.find(x=>x.key===sel)||tours[0];
  if(!t) return <div className="panel none" style={{padding:24}}>데이터 없음</div>;
  const split=(s)=>String(s||"").split("/").map(x=>x.trim()).filter(Boolean);
  return (<>
    <div className="subtabs">{tours.map(x=><button key={x.key} className={"subtab"+(x.key===sel?" on":"")} onClick={()=>setSel(x.key)}>{x.label}</button>)}</div>
    <div className="panel swap" key={sel} style={{paddingBottom:14}}>
      <div style={{display:"flex",alignItems:"center",gap:10,margin:"14px 2px 4px",flexWrap:"wrap"}}>
        <span style={{width:11,height:11,borderRadius:4,background:t.color}}/>
        <h3 style={{margin:0,fontSize:18,fontWeight:800,color:"var(--navy)"}}>{t.label}</h3>
        <span style={{fontSize:12.5,color:"var(--muted)",fontWeight:600}} className="tnum">{t.rounds.length}회</span>
        {admin&&<button className="btn btn-gold btn-sm ed-pencil" onClick={()=>setModal({type:"rounds",title:t.label,rounds:t.rounds,build:(rounds)=>({...data,tournaments:tours.map(x=>x.key===t.key?{...x,rounds}:x)})})}>회차 편집</button>}
      </div>
      {t.rounds.map((r,i)=>{
        const rl=r.round?(/^\d+$/.test(String(r.round))?String(r.round)+"회":r.round):"";
        return (
        <div className={"round2"+(r.champ?" champ":"")} key={i}>
          <div className="r2-date tnum">{r.date}</div>
          <div className="r2-main">
            {(rl||r.rule||r.team||r.champ)&&<div className="r2-head">
              {rl&&<span className="r2-round">{rl}</span>}
              {r.champ&&<span className="r2-champ">챔피언스 시리즈</span>}
              {r.team&&<span className="r2-mode">팀전</span>}
              {r.rule&&<span className="r2-rule">· {r.rule}</span>}
            </div>}
            <div className="r2-res">
              <span className="r2-rk gold">우승</span>
              {r.win&&<span className="r2-name win">{r.win}</span>}
              {r.winMembers&&r.winMembers.length>0&&<NameChips list={r.winMembers} kind="mem"/>}
              {(r.ru||(r.ruMembers&&r.ruMembers.length>0))&&<><span className="r2-rk">준우승</span>{r.team?(r.ru&&<span className="r2-name">{r.ru}</span>):<NameChips list={split(r.ru)}/>}
                {r.ruMembers&&r.ruMembers.length>0&&<NameChips list={r.ruMembers} kind="mem"/>}</>}
              {(r.sf||[]).length>0&&<><span className="r2-rk">4강</span>{r.team
                ?r.sf.map((nm,k)=>(<React.Fragment key={k}>{nm&&<span className="r2-name">{nm}</span>}{(r.sfMembers||[])[k]&&(r.sfMembers[k].length>0)&&<NameChips list={r.sfMembers[k]} kind="mem"/>}</React.Fragment>))
                :<NameChips list={r.sf}/>}</>}
            </div>
          </div>
        </div>);
      })}
    </div>
  </>);
}

/* ============================== TITLES ============================== */
function Titles({ data, admin, setModal }) {
  return (<section className="sec">
    <Reveal className="sec-head"><div className="kick">Titles</div><h2>칭호</h2>
      <p className="sub">특정 조건을 달성한 트레이너에게 주어지는 명예의 칭호 목록입니다.</p>
    </Reveal>
    {data.titleGroups.map((g,gi)=>(<div className="tgroup" key={g.id}>
      <Reveal className="tgroup-head"><span className="ic">{g.icon}</span><h3>{g.name}</h3><span className="cnt tnum">{g.items.length}</span><span className="gdesc">{g.desc}</span>{admin&&<button className="btn btn-gold btn-sm" onClick={()=>setModal({type:"title",groupKey:g.key})}>+ 추가</button>}</Reveal>
      <div className="grid g3">{g.items.map((it,i)=>{const mon=g.key==="partner";const empty=(it.holders||[]).length===0;return (
        <Reveal key={it.id} delay={(i%3)*60} className={"titem"+(empty&&!mon?" empty":"")}>
          <div className="tn">{it.name}</div>{it.desc&&<div className="td">{it.desc}</div>}
          <div className="hold">{(it.holders||[]).length?it.holders.map((h,j)=><span className={"holder"+(mon?" mon-h":"")} key={j}>{h}</span>):<span className="none">미달성</span>}</div>
          {admin&&<div className="edit-row"><button className="btn btn-ghost btn-sm ed-pencil" onClick={()=>setModal({type:"title",groupKey:g.key,item:it})}>수정</button></div>}
        </Reveal>);})}</div>
    </div>))}
  </section>);
}

/* ============================== CHAMPIONS ============================== */
function Champions({ data, admin, setModal }) {
  const champs=[...data.champions].sort((a,b)=>a.season-b.season);
  return (<section className="sec">
    <Reveal className="sec-head"><div className="kick">Hall of Fame</div><h2>명예의 전당</h2>
      <p className="sub">챔피언스 시리즈를 제패한 역대 챔피언과 그 우승 엔트리입니다.</p>
      {admin&&<div className="row-actions"><button className="btn btn-gold btn-sm" onClick={()=>setModal({type:"champion"})}>+ 챔피언 추가</button></div>}
    </Reveal>
    <div className="grid g2">{champs.map((c,i)=>(<Reveal key={c.id} delay={(i%2)*80} className="champ hover">
      <span className="crown">👑</span>
      <div className="gen">👑 {c.gen} 챔피언 · {c.slabel||("SEASON "+c.season)}</div><div className="nm">{c.name}</div>
      <div className="team">{c.team.filter(Boolean).map((m,j)=>{const img=POKE_IMG[m];return (
        <div className={"poke"+(img?"":" noimg")} key={j}>
          <div className="sp">{img?<img src={img} alt={m} loading="lazy"/>:<span className="ph">{m}</span>}</div>
          {img&&<div className="pn">{m}</div>}
        </div>);})}</div>
      {admin&&<div className="edit-row"><button className="btn btn-ghost btn-sm ed-pencil" onClick={()=>setModal({type:"champion",item:c})}>수정</button></div>}
    </Reveal>))}</div>
  </section>);
}

/* ============================== 에디터 ============================== */
function LoginModal({ onClose, onSuccess }) {
  const [id,setId]=useState(""),[pw,setPw]=useState(""),[err,setErr]=useState("");
  const submit=()=>ADMINS.some(a=>a.id===id.trim()&&a.pw===pw)?onSuccess():setErr("아이디 또는 비밀번호가 올바르지 않습니다.");
  return (<Modal title="관리자 로그인" hint="운영진 전용. 계정은 코드 상단 ADMINS 에서 변경합니다." onClose={onClose}>
    <div className="field"><label>아이디</label><input value={id} onChange={e=>setId(e.target.value)} placeholder="yplofficial"/></div>
    <div className="field"><label>비밀번호</label><input type="password" value={pw} onChange={e=>setPw(e.target.value)} onKeyDown={e=>e.key==="Enter"&&submit()}/></div>
    {err&&<div style={{color:"var(--loss)",fontSize:13,marginTop:-6}}>{err}</div>}
    <div className="modal-actions"><button className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary" onClick={submit}>로그인</button></div>
  </Modal>);
}
function MetaEditor({ meta, onClose, onSave }) {
  const [m,setM]=useState({...meta}); const f=k=>e=>setM({...m,[k]:e.target.value});
  return (<Modal title="메인 정보 수정" onClose={onClose}>
    <div className="field"><label>리그 풀네임</label><input value={m.fullName} onChange={f("fullName")}/></div>
    <div className="field"><label>태그라인</label><input value={m.tagline} onChange={f("tagline")}/></div>
    <div className="field"><label>현 챔피언 대수</label><input value={m.currentChampionGen} onChange={f("currentChampionGen")} placeholder="5대"/></div>
    <div className="field"><label>현 챔피언</label><input value={m.currentChampion} onChange={f("currentChampion")}/></div>
    <div className="field"><label>홈 소개글</label><textarea value={m.intro} onChange={f("intro")}/></div>
    <div className="modal-actions"><button className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary" onClick={()=>onSave(m)}>저장</button></div>
  </Modal>);
}
function ChampionEditor({ item, onClose, onSave, onDelete }) {
  const [gen,setGen]=useState(item?.gen||""),[season,setSeason]=useState(item?.season||""),[name,setName]=useState(item?.name||""),[raw,setRaw]=useState((item?.team||[]).join("\n"));
  const submit=()=>onSave({id:item?.id||uid(),gen:gen.trim(),season:parseInt(season)||0,name:name.trim(),team:raw.split("\n").map(s=>s.trim()).filter(Boolean)});
  return (<Modal title={item?"챔피언 수정":"챔피언 추가"} hint="우승 포켓몬은 한 줄에 한 마리씩." onClose={onClose}>
    <div className="field"><label>대수</label><input value={gen} onChange={e=>setGen(e.target.value)} placeholder="6대"/></div>
    <div className="field"><label>시즌 번호</label><input value={season} onChange={e=>setSeason(e.target.value)} placeholder="6"/></div>
    <div className="field"><label>챔피언 이름</label><input value={name} onChange={e=>setName(e.target.value)}/></div>
    <div className="field"><label>우승 엔트리</label><textarea value={raw} onChange={e=>setRaw(e.target.value)} style={{minHeight:130}}/></div>
    <div className="modal-actions">{onDelete&&<button className="btn btn-danger" onClick={onDelete} style={{marginRight:"auto"}}>삭제</button>}<button className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary" onClick={submit}>저장</button></div>
  </Modal>);
}
function TitleItemEditor({ groupKey, item, onClose, onSave, onDelete }) {
  const partner=groupKey==="partner";
  const [name,setName]=useState(item?.name||""),[desc,setDesc]=useState(item?.desc||""),[raw,setRaw]=useState((item?.holders||[]).join("\n"));
  const submit=()=>onSave({id:item?.id||uid(),name:name.trim(),desc:desc.trim()||undefined,holders:raw.split("\n").map(s=>s.trim()).filter(Boolean)});
  return (<Modal title={item?"칭호 수정":"칭호 추가"} hint={partner?"이름=트레이너, 아래엔 파트너 포켓몬을 한 줄에 하나씩.":"해당자를 한 줄에 한 명씩 입력하세요."} onClose={onClose}>
    <div className="field"><label>{partner?"트레이너":"칭호 이름"}</label><input value={name} onChange={e=>setName(e.target.value)}/></div>
    {!partner&&<div className="field"><label>설명 (선택)</label><input value={desc} onChange={e=>setDesc(e.target.value)}/></div>}
    <div className="field"><label>{partner?"파트너 포켓몬":"해당자"}</label><textarea value={raw} onChange={e=>setRaw(e.target.value)}/></div>
    <div className="modal-actions">{onDelete&&<button className="btn btn-danger" onClick={onDelete} style={{marginRight:"auto"}}>삭제</button>}<button className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary" onClick={submit}>저장</button></div>
  </Modal>);
}
function AnnEditor({ item, onClose, onSave, onDelete }) {
  const [date,setDate]=useState(item?.date||new Date().toISOString().slice(0,10)),[title,setTitle]=useState(item?.title||""),[body,setBody]=useState(item?.body||""),[pinned,setPinned]=useState(item?.pinned||false);
  return (<Modal title={item?"공지 수정":"공지 작성"} onClose={onClose}>
    <div className="field"><label>날짜</label><input value={date} onChange={e=>setDate(e.target.value)} placeholder="2024-05-26"/></div>
    <div className="field"><label>제목</label><input value={title} onChange={e=>setTitle(e.target.value)}/></div>
    <div className="field"><label>내용</label><textarea value={body} onChange={e=>setBody(e.target.value)} style={{minHeight:120}}/></div>
    <div className="field" style={{display:"flex",alignItems:"center",gap:10}}><input type="checkbox" checked={pinned} onChange={e=>setPinned(e.target.checked)} style={{width:"auto"}} id="pin"/><label htmlFor="pin" style={{margin:0}}>상단 고정</label></div>
    <div className="modal-actions">{onDelete&&<button className="btn btn-danger" onClick={onDelete} style={{marginRight:"auto"}}>삭제</button>}<button className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary" onClick={()=>onSave({id:item?.id||uid(),date,title:title.trim()||"(제목 없음)",body,pinned})}>저장</button></div>
  </Modal>);
}
function StandingsEditor({ title, rows, onClose, onSave }) {
  const [list,setList]=useState(rows.map(r=>({...r})));
  const upd=(i,k,v)=>setList(list.map((r,j)=>j===i?{...r,[k]:v}:r));
  const del=(i)=>setList(list.filter((_,j)=>j!==i));
  const add=()=>setList([...list,{name:"",win:0,ru:0,top4:0,points:0}]);
  const submit=()=>onSave(list.filter(r=>r.name&&r.name.trim()).map(r=>({name:r.name.trim(),win:+r.win||0,ru:+r.ru||0,top4:+r.top4||0,points:+r.points||0,...(r.note?{note:r.note}:{})})));
  return (<Modal title={`${title} 수정`} hint="이름과 성적을 입력하세요. 표시는 포인트 순으로 자동 정렬됩니다." onClose={onClose}>
    <div className="ed-grid ed-head"><span>트레이너</span><span>우승</span><span>준우승</span><span>4강</span><span>포인트</span><span/></div>
    <div className="ed-scroll">{list.map((r,i)=>(<div className="ed-grid" key={i}>
      <input value={r.name} onChange={e=>upd(i,"name",e.target.value)} placeholder="이름"/>
      <input type="number" value={r.win} onChange={e=>upd(i,"win",e.target.value)}/>
      <input type="number" value={r.ru} onChange={e=>upd(i,"ru",e.target.value)}/>
      <input type="number" value={r.top4} onChange={e=>upd(i,"top4",e.target.value)}/>
      <input type="number" value={r.points} onChange={e=>upd(i,"points",e.target.value)}/>
      <button className="ed-del" onClick={()=>del(i)} title="삭제">✕</button>
    </div>))}</div>
    <button className="btn btn-ghost btn-sm" style={{marginTop:12}} onClick={add}>+ 트레이너 추가</button>
    <div className="modal-actions"><button className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary" onClick={submit}>저장</button></div>
  </Modal>);
}
function RoundsEditor({ title, rounds, onClose, onSave }) {
  const splitL=(s)=>String(s||"").split(/[,\n]/).map(x=>x.trim()).filter(Boolean);
  const dkey=(d)=>{const m=String(d||"").match(/\d+/g)||[];return (+(m[0]||0))*1e8+(+(m[1]||0))*1e6+(+(m[2]||0))*1e4;};
  const rkey=(rd)=>{const n=parseInt(String(rd||""),10);return isNaN(n)?999999:n;};
  const sortRows=(arr)=>arr.map((r,i)=>({r,i})).sort((a,b)=>(dkey(a.r.date)-dkey(b.r.date))||(rkey(a.r.round)-rkey(b.r.round))||(a.i-b.i)).map(x=>x.r);
  const init=(r)=>({
    team:!!r.team, champ:!!r.champ, date:r.date||"", round:r.round||"", rule:r.rule||"",
    win:r.win||"", ru:r.ru||"",
    winM:(r.winMembers||[]).join(", "), ruM:(r.ruMembers||[]).join(", "),
    sfText:r.team?"":(r.sf||[]).join(", "),
    sfTeams:r.team?(r.sf||[]).map((nm,i)=>({name:nm,mem:((r.sfMembers||[])[i]||[]).join(", ")})):[],
  });
  const [list,setList]=useState(rounds.map(init));
  const [autoSort,setAutoSort]=useState(true);
  const upd=(i,k,v)=>setList(list.map((r,j)=>j===i?{...r,[k]:v}:r));
  const del=(i)=>setList(list.filter((_,j)=>j!==i));
  const add=()=>setList([...list,init({})]);
  const moveUp=(i)=>{if(i<=0)return;setAutoSort(false);setList(arr=>{const a=[...arr];[a[i-1],a[i]]=[a[i],a[i-1]];return a;});};
  const moveDown=(i)=>{setAutoSort(false);setList(arr=>{if(i>=arr.length-1)return arr;const a=[...arr];[a[i],a[i+1]]=[a[i+1],a[i]];return a;});};
  const sortNow=()=>{setAutoSort(true);setList(arr=>sortRows(arr));};
  const sfUpd=(i,k,key,v)=>setList(list.map((r,j)=>j!==i?r:{...r,sfTeams:r.sfTeams.map((t,m)=>m===k?{...t,[key]:v}:t)}));
  const sfAdd=(i)=>setList(list.map((r,j)=>j===i?{...r,sfTeams:[...r.sfTeams,{name:"",mem:""}]}:r));
  const sfDel=(i,k)=>setList(list.map((r,j)=>j===i?{...r,sfTeams:r.sfTeams.filter((_,m)=>m!==k)}:r));
  const submit=()=>{
    let out=list.filter(r=>r.team?(String(r.win).trim()||splitL(r.winM).length>0):String(r.win).trim()).map(r=>{
      const base={date:String(r.date).trim(),round:String(r.round).trim(),rule:String(r.rule).trim(),win:String(r.win).trim(),ru:String(r.ru).trim()};
      const champ=r.champ?{champ:true}:{};
      if(r.team){
        const sfT=r.sfTeams.filter(t=>String(t.name).trim()||splitL(t.mem).length>0);
        return {...base,...champ,team:true,winMembers:splitL(r.winM),ruMembers:splitL(r.ruM),sf:sfT.map(t=>t.name.trim()),sfMembers:sfT.map(t=>splitL(t.mem))};
      }
      return {...base,...champ,team:false,sf:splitL(r.sfText)};
    });
    if(autoSort) out=sortRows(out);
    onSave(out);
  };
  return (<Modal title={`${title} 회차 수정`} hint="개인전/팀전·일반/챔피언스 시리즈를 고르고 결과를 입력하세요. 저장 시 날짜순으로 자동 정렬됩니다(▲▼로 직접 순서 변경 가능)." onClose={onClose}>
    <div className="pts-note" style={{marginBottom:14}}>포인트 기준 — 우승 <b>60</b> · 준우승 <b>40</b> · 4강 <b>20</b>점 (팀전 여부·팀원 수·대회 사정에 따라 변동될 수 있어, 누적 포인트는 랭킹 편집에서 직접 입력합니다.)</div>
    <div style={{display:"flex",alignItems:"center",gap:12,flexWrap:"wrap",marginBottom:14}}>
      <button className="btn btn-ghost btn-sm" onClick={add}>+ 회차 추가 (맨 아래)</button>
      <button className="btn btn-ghost btn-sm" onClick={sortNow}>↕ 날짜순 정렬</button>
      <label className="ed-auto"><input type="checkbox" checked={autoSort} onChange={e=>setAutoSort(e.target.checked)}/> 저장 시 자동 날짜정렬</label>
    </div>
    <div className="ed-scroll">{list.map((r,i)=>(<div className="ed-round" key={i}>
      <div className="ed-rtop"><input className="ed-w" value={r.date} onChange={e=>upd(i,"date",e.target.value)} placeholder="날짜 (2025.06)"/><input className="ed-w" value={r.round} onChange={e=>upd(i,"round",e.target.value)} placeholder="회차"/><button className="ed-mv" onClick={()=>moveUp(i)} disabled={i===0} title="위로">▲</button><button className="ed-mv" onClick={()=>moveDown(i)} disabled={i===list.length-1} title="아래로">▼</button><button className="ed-del" onClick={()=>del(i)} title="삭제">✕</button></div>
      <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
        <div className="ed-seg"><button type="button" className={!r.team?"on":""} onClick={()=>upd(i,"team",false)}>개인전</button><button type="button" className={r.team?"on":""} onClick={()=>upd(i,"team",true)}>팀전</button></div>
        <div className="ed-seg"><button type="button" className={!r.champ?"on":""} onClick={()=>upd(i,"champ",false)}>일반</button><button type="button" className={r.champ?"on":""} onClick={()=>upd(i,"champ",true)}>챔피언스 시리즈</button></div>
      </div>
      {!r.team?<>
        <div className="ed-r2"><input value={r.win} onChange={e=>upd(i,"win",e.target.value)} placeholder="🏆 우승"/><input value={r.ru} onChange={e=>upd(i,"ru",e.target.value)} placeholder="준우승"/></div>
        <input value={r.sfText} onChange={e=>upd(i,"sfText",e.target.value)} placeholder="4강 (쉼표 구분)"/>
      </>:<>
        <div className="ed-team"><span className="ed-rk gold">🏆 우승 팀</span>
          <input value={r.win} onChange={e=>upd(i,"win",e.target.value)} placeholder="팀 이름 (선택)"/>
          <input value={r.winM} onChange={e=>upd(i,"winM",e.target.value)} placeholder="팀원 (쉼표 구분, 인원 제한 없음)"/></div>
        <div className="ed-team"><span className="ed-rk">준우승 팀</span>
          <input value={r.ru} onChange={e=>upd(i,"ru",e.target.value)} placeholder="팀 이름 (선택)"/>
          <input value={r.ruM} onChange={e=>upd(i,"ruM",e.target.value)} placeholder="팀원 (쉼표 구분)"/></div>
        {r.sfTeams.map((t,k)=>(<div className="ed-team" key={k}><span className="ed-rk">4강 팀 {k+1} <button className="ed-x" onClick={()=>sfDel(i,k)}>✕</button></span>
          <input value={t.name} onChange={e=>sfUpd(i,k,"name",e.target.value)} placeholder="팀 이름 (선택)"/>
          <input value={t.mem} onChange={e=>sfUpd(i,k,"mem",e.target.value)} placeholder="팀원 (쉼표 구분)"/></div>))}
        <button className="btn btn-ghost btn-sm" onClick={()=>sfAdd(i)} style={{alignSelf:"flex-start"}}>+ 4강 팀 추가</button>
      </>}
      <input value={r.rule} onChange={e=>upd(i,"rule",e.target.value)} placeholder="룰 (예: 모노타입 / 6세대 63 팀전)"/>
    </div>))}</div>
    <div className="modal-actions"><button className="btn btn-ghost" onClick={onClose}>취소</button><button className="btn btn-primary" onClick={submit}>저장</button></div>
  </Modal>);
}
